const fn = new Function(code + "\nreturn { withLock };");
const { withLock } = fn();
const events = [];
const lock = { acquire: async () => { events.push("acquire"); }, release: async () => { events.push("release"); } };
const out = await withLock(lock, async () => { events.push("job"); return 42; });
if (out !== 42) throw new Error("The job result should be returned.");
if (events.join() !== "acquire,job,release") throw new Error("Order must be acquire, job, release.");

